class PatchError(Exception):
    pass


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def section_table(data):
    pe = struct.unpack_from("<I", data, 0x3C)[0]
    nsec = struct.unpack_from("<H", data, pe + 6)[0]
    opt_size = struct.unpack_from("<H", data, pe + 20)[0]
    table = pe + 24 + opt_size
    secs = []
    for i in range(nsec):
        o = table + 40 * i
        name = data[o:o + 8].rstrip(b"\0").decode("ascii", "replace")
        vsize, va, rsize, raw = struct.unpack_from("<IIII", data, o + 8)
        secs.append((name, va, vsize, raw, rsize))
    return secs


def rva_to_off(data, rva):
    for _name, va, vsize, raw, rsize in section_table(data):
        if va <= rva < va + max(vsize, rsize):
            return rva - va + raw
    raise PatchError(f"RVA {rva:#x} không thuộc section nào")


def read_at(data, rva, n):
    off = rva_to_off(data, rva)
    return bytes(data[off:off + n])


def has_payload(data):
    return any(s[0] == ".hvnj" for s in section_table(data))


def cfg_offset(data):
    """File offset của khối cfg (đầu section .hvnjd). Tìm theo section chứ không theo
    PAYLOAD_DATA_RVA vì DLL dựng từ payload cũ hơn có thể đặt .hvnjd ở RVA khác."""
    return next(raw for name, _va, _vs, raw, _rs in section_table(data) if name == ".hvnjd")


def payload_version(data):
    """cfg_version trong khối cfg: 2 = bản chọn tính năng bằng script, 3 = menu trong game."""
    return data[cfg_offset(data) + 4] if has_payload(data) else 0


# ==============================================================================
# KHÔI PHỤC BẢN GỐC
# ==============================================================================
def strip_payload(data):
    """DLL do script này tạo (bản v2 hoặc v3) -> bản gốc (cắt section mới, trả byte gốc)."""
    buf = bytearray(data[:ORIGINAL_SIZE])
    for off, o, _n in PAYLOAD_HEADER_PATCHES:
        ob = bytes.fromhex(o)
        buf[off:off + len(ob)] = ob
    entries = [e for lst in list(V2_SIMPLE_PATCHES.values()) + list(RETIRED_PATCHES.values()) for e in lst]
    for rva, o, _n in entries + PAYLOAD_HOOKS:
        off = rva_to_off(buf, rva)
        ob = bytes.fromhex(o)
        buf[off:off + len(ob)] = ob
    return bytes(buf)


def strip_legacy(data):
    """Bản mod cũ v1 -> bản gốc: ghi lại byte gốc ở mọi vị trí v1 từng sửa
    (kết quả được kiểm tra lại bằng SHA-256 ở nơi gọi)."""
    if len(data) != ORIGINAL_SIZE:
        return None
    buf = bytearray(data)
    entries = [(off, o) for lst in LEGACY_PATCHES.values() for off, o, _p in lst] + LEGACY_SHARED
    for off, o in entries:
        ob = bytes.fromhex(o)
        buf[off:off + len(ob)] = ob
    off = LEGACY_QUEST_CAVE_OFFSET
    buf[off:off + len(LEGACY_QUEST_CAVE_ORIG)] = LEGACY_QUEST_CAVE_ORIG
    return bytes(buf)


def find_original(dll_path):
    """Trả về (bytes gốc, nguồn)."""
    cur = open(dll_path, "rb").read()
    if sha256(cur) == ORIGINAL_SHA256:
        return cur, "file hiện tại"
    bak = dll_path + BAK_SUFFIX
    if os.path.exists(bak):
        b = open(bak, "rb").read()
        if sha256(b) == ORIGINAL_SHA256:
            return b, os.path.basename(bak)
        rec = strip_payload(b) if has_payload(b) else strip_legacy(b)
        if rec is not None and sha256(rec) == ORIGINAL_SHA256:
            return rec, f"khôi phục từ {os.path.basename(bak)}"
    rec = strip_payload(cur) if has_payload(cur) else strip_legacy(cur)
    if rec is not None and sha256(rec) == ORIGINAL_SHA256:
        return rec, "khôi phục từ DLL đã mod"
    raise PatchError(
        "Không tìm được GameAssembly.dll gốc của bản 186 (SHA-256 không khớp).\n"
        "    Có thể game đã cập nhật phiên bản khác - các offset của mod không còn đúng.\n"
        "    Hãy cài lại / kiểm tra file game để có GameAssembly.dll bản 186 gốc rồi chạy lại.")


# ==============================================================================
# NHẬN DIỆN TRẠNG THÁI
# ==============================================================================
KIND_ORIGINAL = "gốc"
KIND_V1 = "mod cũ v1"
KIND_V2 = "mod cũ v2"
KIND_V3 = "mod v3 (bật / tắt bằng menu trong game)"
KIND_UNKNOWN = "đã bị sửa, không rõ"


def detect_retired(data):
    """Các tính năng đã gỡ nhưng vẫn còn trong DLL."""
    return {feat for feat, lst in RETIRED_PATCHES.items()
            if all(read_at(data, rva, len(n) // 2) == bytes.fromhex(n) for rva, _o, n in lst)}


def detect(data):
    """Trả về (kiểu bản build, tập tính năng đang bật ở bản cũ chọn bằng script)."""
    if sha256(data) == ORIGINAL_SHA256:
        return KIND_ORIGINAL, set()
    if has_payload(data) and payload_version(data) >= PAYLOAD_VERSION:
        return KIND_V3, set()
    if len(data) == ORIGINAL_SIZE and not has_payload(data):
        legacy = set()
        for feat, lst in LEGACY_PATCHES.items():
            if all(data[off:off + len(p) // 2] == bytes.fromhex(p) for off, _o, p in lst if p):
                legacy.add(feat)
        # skill/die của v1 và v2 giống hệt byte; chỉ coi là v1 khi có dấu vết riêng của v1
        if legacy & {"mob", "trial", "stage", "quest"}:
            return KIND_V1, legacy & set(OLD_FEATURE_FLAGS)
    on = {feat for feat, lst in V2_SIMPLE_PATCHES.items()
          if all(read_at(data, rva, len(n) // 2) == bytes.fromhex(n) for rva, _o, n in lst)}
    if has_payload(data):
        cfg = cfg_offset(data)
        on |= {feat for feat, o in V2_CFG.items() if data[cfg + o]}
        return KIND_V2, on
    if on or detect_retired(data):
        return KIND_V2, on
    return KIND_UNKNOWN, set()


# ==============================================================================
# DỰNG DLL
# ==============================================================================
def build(original):
    """Bản gốc -> DLL đã cài mod (mọi tính năng tắt cho tới khi tick trong menu)."""
    buf = bytearray(original)

    def put(rva, o, n):
        off = rva_to_off(buf, rva)
        ob, nb = bytes.fromhex(o), bytes.fromhex(n)
        if buf[off:off + len(ob)] != ob:
            raise PatchError(f"Byte gốc không khớp tại RVA {rva:#x}")
        buf[off:off + len(nb)] = nb

    for off, o, n in PAYLOAD_HEADER_PATCHES:
        ob, nb = bytes.fromhex(o), bytes.fromhex(n)
        if buf[off:off + len(ob)] != ob:
            raise PatchError(f"PE header không khớp tại {off:#x}")
        buf[off:off + len(nb)] = nb
    assert len(buf) == PAYLOAD_CODE_RAW
    buf += PAYLOAD_CODE
    assert len(buf) == PAYLOAD_DATA_RAW
    buf += PAYLOAD_DATA
    for rva, o, n in PAYLOAD_HOOKS:
        put(rva, o, n)
    return bytes(buf)


def write_atomic(path, data):
    tmp = path + ".tmp"
    with open(tmp, "wb") as f:
        f.write(data)
    try:
        os.replace(tmp, path)
    except PermissionError:
        os.remove(tmp)
        raise PatchError(f"Không ghi được {path}. Hãy tắt game trước khi chạy script.")


def ensure_backup(dll_path, original):
    bak = dll_path + BAK_SUFFIX
    if os.path.exists(bak):
        if sha256(open(bak, "rb").read()) == ORIGINAL_SHA256:
            return
        keep = bak + ".khong-phai-ban-goc"
        os.replace(bak, keep)
        print(f"[!] {os.path.basename(bak)} không phải bản gốc -> đổi tên thành {os.path.basename(keep)}")
    write_atomic(bak, original)
    print(f"[+] Đã lưu bản gốc vào {os.path.basename(bak)}")


def print_status(dll_path):
    data = open(dll_path, "rb").read()
    kind, old = detect(data)
    print(f"=== TRẠNG THÁI {dll_path} ({kind}) ===")
    if kind == KIND_V3:
        print("[+] Đã cài mod. Bật / tắt từng tính năng TRONG GAME:")
        print("    menu nhân vật -> dòng cuối \"Mod HVNJ\" -> bấm vào dòng để tick [x] / bỏ tick [   ].")
        print("    Mặc định tắt hết; lựa chọn được lưu cho lần mở game sau. Các dòng của menu:")
        for i, name in enumerate(MENU_ITEMS, 1):
            print(f"    {i:2}. {name}")
    elif kind == KIND_ORIGINAL:
        print("[ ] Chưa cài mod. Chạy: python patch_skill_delay.py --install")
    elif kind in (KIND_V1, KIND_V2):
        feats = ", ".join(sorted(old)) or "(không tính năng nào)"
        print(f"[!] Bản mod cũ chọn tính năng bằng script: {feats}.")
        print("    Chạy: python patch_skill_delay.py --install  để nâng cấp lên bản bật / tắt bằng menu trong game.")
    else:
        print("[!] DLL đã bị sửa nhưng không nhận ra bản mod nào.")
    if "skill" in detect_retired(data):
        print("[!] Còn patch 'tốc độ ra chiêu 0.3s' (đã gỡ vì chỉ làm chậm hiệu ứng). Chạy --install để gỡ.")
    print("=" * 50)


def main(argv=None):
    ap = argparse.ArgumentParser(
        description="Bản mod Học Viện Ninja 186. Script chỉ CÀI / GỠ mod; bật / tắt từng tính năng "
                    "bằng menu \"Mod HVNJ\" trong game (menu nhân vật).")
    ap.add_argument("--dll", default=GAME_DLL, help="đường dẫn GameAssembly.dll (mặc định: thư mục hiện tại)")
    ap.add_argument("--install", "--all", "--full", action="store_true",
                    help="cài (hoặc cập nhật) mod; tính năng bật / tắt trong game")
    ap.add_argument("--restore", action="store_true", help="gỡ mod, khôi phục GameAssembly.dll gốc")
    ap.add_argument("--status", action="store_true", help="xem trạng thái")
    # tham số của các bản trước: vẫn nhận để lệnh cũ không lỗi, nhưng giờ chỉ có nghĩa "cài mod"
    for f in OLD_FEATURE_FLAGS + ["skill"]:
        ap.add_argument("--" + f, action="store_true", help=argparse.SUPPRESS)
    ap.add_argument("--remove", nargs="+", help=argparse.SUPPRESS)
    for f in ("--accept-option", "--stone-pay", "--stone-levels"):
        ap.add_argument(f, help=argparse.SUPPRESS)
    args = ap.parse_args(argv)

    dll = args.dll
    if not os.path.exists(dll):
        print(f"[-] Không tìm thấy {dll}. Chạy script trong thư mục game hoặc dùng --dll.")
        return 1
    old_flags = [f for f in OLD_FEATURE_FLAGS if getattr(args, f)]
    old_opts = [n for n, v in (("--accept-option", args.accept_option), ("--stone-pay", args.stone_pay),
                               ("--stone-levels", args.stone_levels)) if v is not None]
    if args.skill:
        print("[!] Tính năng 'tốc độ ra chiêu 0.3s' đã bị gỡ: patch cũ chỉ làm hiệu ứng skill chạy chậm,"
              " không giảm hồi chiêu.")
    if old_flags or old_opts or args.remove:
        print("[!] Từ bản này, tính năng và tùy chọn được bật / tắt bằng menu \"Mod HVNJ\" trong game "
              f"({' '.join(['--' + f for f in old_flags] + old_opts + (['--remove'] if args.remove else []))} "
              "không còn tác dụng). Script chỉ cài / gỡ mod.")
    install = args.install or bool(old_flags or old_opts)
    if not (install or args.restore or args.status):
        if not (args.skill or args.remove):
            ap.print_help()
        return 0
    try:
        if args.status:
            print_status(dll)
            return 0
        original, source = find_original(dll)
        print(f"[*] Bản gốc: {source}")
        ensure_backup(dll, original)
        if args.restore:
            write_atomic(dll, original)
            print(f"[+] Đã khôi phục {dll} về bản gốc.")
        else:
            write_atomic(dll, build(original))
            print(f"[+] Đã cài mod vào {dll}. Vào game: menu nhân vật -> \"Mod HVNJ\" để bật tính năng.")
        print_status(dll)
    except PatchError as e:
        print(f"[-] {e}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
